mapper.update:
UPDATE house
title = #{title}, description = #{description}, address = #{address}, province = #{province}, city = #{city}, district = #{district}, latitude = #{latitude}, longitude = #{longitude}, price = #{price}, deposit = #{deposit}, area = #{area}, room_count = #{roomCount}, hall_count = #{hallCount}, bathroom_count = #{bathroomCount}, floor = #{floor}, total_floor = #{totalFloor}, orientation = #{orientation}, rent_type = #{rentType}, available_date = #{availableDate}, utilities = #{utilities}, requirements = #{requirements}, status = #{status}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT * FROM house
WHERE status = 1

    AND city = #{city}


    AND district = #{district}


    AND price >= #{minPrice}


    AND price <= #{maxPrice}


    AND rent_type = #{rentType}


    AND room_count = #{roomCount}


    AND (title LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%')
         OR address LIKE CONCAT('%', #{keyword}, '%'))


    ORDER BY price ASC
    ORDER BY price DESC
    ORDER BY create_time DESC
    ORDER BY create_time DESC

SELECT h.id, h.title, h.price, h.city, h.district, h.address,
       h.area, h.room_count, h.hall_count, h.bathroom_count,
       ROUND(AVG(r.rating), 1) AS avgRating,
       COUNT(r.id) AS reviewCount
FROM house h
LEFT JOIN review r ON r.house_id = h.id
WHERE h.status = 1

    AND h.city = #{city}


    AND h.district = #{district}


    AND h.price <= #{maxPrice}

GROUP BY h.id
ORDER BY COUNT(r.id) DESC, AVG(r.rating) DESC, h.create_time DESC
LIMIT #{limit}
